ALTER TABLE public.telegram_account_links ADD COLUMN notify_account boolean NOT NULL DEFAULT false, ADD COLUMN notify_announcements boolean NOT NULL DEFAULT false;
ALTER TABLE public.telegram_admin_config ADD COLUMN commissioning_confirmed_at timestamptz, ADD COLUMN original_qr_file_id text;
ALTER TABLE public.telegram_deliveries ADD COLUMN delivery_method text NOT NULL DEFAULT 'sendMessage', ADD COLUMN payload jsonb, ADD COLUMN website_user_id uuid, ADD COLUMN generation_id uuid, ADD COLUMN update_id bigint;
CREATE INDEX telegram_delivery_pending_idx ON public.telegram_deliveries(status,created_at);
CREATE OR REPLACE FUNCTION public.telegram_claim_delivery(_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.telegram_deliveries SET status='sending',attempts=attempts+1 WHERE id=_id AND status='pending'; RETURN FOUND; END; $$;
REVOKE ALL ON FUNCTION public.telegram_claim_delivery(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.telegram_claim_delivery(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.telegram_set_activation(_owner uuid,_enabled boolean,_accepted boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.telegram_admin_config; BEGIN SELECT * INTO c FROM public.telegram_admin_config WHERE id=true FOR UPDATE; IF c.website_owner_id<>_owner OR NOT public.has_role(_owner,'admin'::public.app_role) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF _enabled AND (c.owner_verified_at IS NULL OR NOT _accepted OR c.last_health_check IS NULL OR c.last_health_check<now()-interval '15 minutes' OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(c.health->'checks','[]'::jsonb)) x WHERE x->>'status'='failed')) THEN RAISE EXCEPTION 'COMMISSIONING_REQUIRED'; END IF; UPDATE public.telegram_admin_config SET enabled=_enabled,commissioning_confirmed_at=CASE WHEN _enabled THEN now() ELSE NULL END WHERE id=true; INSERT INTO public.admin_audit_log(admin_id,action,details) VALUES(_owner,'telegram_activation',jsonb_build_object('enabled',_enabled,'acceptance_confirmed',_accepted)); RETURN _enabled; END; $$;
REVOKE ALL ON FUNCTION public.telegram_set_activation(uuid,boolean,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.telegram_set_activation(uuid,boolean,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.telegram_queue_generation_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.telegram_account_links; c public.telegram_admin_config; BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('done','failed') THEN SELECT * INTO c FROM public.telegram_admin_config WHERE id=true; SELECT * INTO l FROM public.telegram_account_links WHERE website_user_id=NEW.user_id AND notify_account=true; IF c.enabled AND l.telegram_user_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND coalesce(notify_generation,true)) THEN INSERT INTO public.telegram_deliveries(dedupe_key,chat_id,message,website_user_id) VALUES('generation:'||NEW.id::text||':'||NEW.status,l.telegram_user_id,'Modern Nova AI: generation '||NEW.id::text||' is '||NEW.status||'. Open https://modernnova.in/history or use /files privately.',NEW.user_id) ON CONFLICT DO NOTHING; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER telegram_generation_notice AFTER UPDATE ON public.generations FOR EACH ROW EXECUTE FUNCTION public.telegram_queue_generation_notice();
CREATE OR REPLACE FUNCTION public.telegram_queue_payment_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.telegram_account_links; c public.telegram_admin_config; BEGIN IF NEW.status IS DISTINCT FROM OLD.status THEN SELECT * INTO c FROM public.telegram_admin_config WHERE id=true; SELECT * INTO l FROM public.telegram_account_links WHERE website_user_id=NEW.user_id AND notify_account=true; IF c.enabled AND l.telegram_user_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND coalesce(notify_payment,true)) THEN INSERT INTO public.telegram_deliveries(dedupe_key,chat_id,message,website_user_id) VALUES('payment:'||NEW.order_id||':'||NEW.status,l.telegram_user_id,'Modern Nova AI: order '||NEW.order_id||' is '||NEW.status||'. Check https://modernnova.in/payments for verified details.',NEW.user_id) ON CONFLICT DO NOTHING; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER telegram_payment_notice AFTER UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.telegram_queue_payment_notice();